<?php namespace App\Http\Controllers; use App\Core\DB; use App\Core\Request; class NoteController { public function index() { $notes = DB::select('SELECT * FROM notes'); return view('notes.index', ['notes' => $notes]); } public function create() { return view('notes.create'); } public function store(Request $request) { DB::insert('INSERT INTO notes (title, content) VALUES (?, ?)', [$request->input('title'), $request->input('content')]); return redirect()->route('notes.index'); } }